"""Explain the proposal and experiments in reading order, using saved results only."""
import html
import json
import re
from pathlib import Path
from statistics import mean

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output/html'
H=html.escape
def load(run,file):return json.loads((ROOT/'runs'/run/file).read_text(encoding='utf-8'))
DISC='signal-visibility-luna-20260919'
REPL='signal-visibility-replication-20260920'
ds,rs=load(DISC,'summary.json'),load(REPL,'summary.json')
rm=load(REPL,'manifest.json'); roots=load(REPL,'roots.json'); updates=load(REPL,'updates.json')
case=rm['items'][0];root=roots['demand-00'];receiver=root['targets'][0]
assert receiver==3 and root['pair_A_B']==[4,1]
def casep(v,a):return mean(r['parsed']['p_B'] for r in updates if r['item_id']=='demand-00' and r['member']==receiver and r['visibility']==v and r['arm']==a)

parts=[];toc=[]
def p(text):parts.append('<p>'+H(text)+'</p>')
def sub(title):parts.append('<h3>'+H(title)+'</h3>')
def conclusion(text):parts.append('<div class="conclusion"><strong>到这里能得出的结论</strong><p>'+H(text)+'</p></div>')
def example(title,text):parts.append('<div class="example"><strong>'+H(title)+'</strong><p>'+H(text)+'</p></div>')
def table(headers,rows):
    parts.append('<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th>'+H(str(c))+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+H(str(c))+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>')
def section(sid,title,lead):
    if toc:parts.append('</section>')
    toc.append((sid,title));parts.append(f'<section id="{sid}"><div class="num">{len(toc):02d}</div><h2>{H(title)}</h2><p class="lead">{H(lead)}</p>')
def detail(title):parts.append('<details><summary>'+H(title)+'</summary>')
def enddetail():parts.append('</details>')
def steps(items):parts.append('<ol class="steps">'+''.join('<li><strong>'+H(a)+'</strong><p>'+H(b)+'</p></li>' for a,b in items)+'</ol>')

section('goal','proposal 到底想研究什么？','先理解问题，再看实验。我们研究的是：同样一组模型，能否仅仅因为“谁显得更有把握”，就走向不同的群体判断。')
p('proposal 的题目是 From Confidence to Consensus: Collective Decision Dynamics of LLM Agents，可以理解为“从置信度到共识：语言模型群体如何形成判断”。这里有两个相连的目标：先测清楚一个模型怎样受到同伴分数影响，再看这种影响能不能帮助我们预测一群模型后续的讨论结果。')
p('这里的 agent，是一个单独接收题目和消息、然后给出回答的模型实例。六个 agent 可以使用同一个模型，但各自独立作答。它们没有上下级，也没有谁负责给 subagent 派任务。我们控制的是它们互相能看到什么。')
sub('为什么值得研究这个问题？')
p('假设几个模型一起帮助用户作决定。一个说“我选 A，有 60% 把握”，另一个说“我选 B，有 90% 把握”。接收建议的模型可能更倾向 B。可是，它倾向 B 究竟是因为 B 的证据更好，还是仅仅因为第二个人写了更大的数字？如果证据和数字一起改变，就分不清这两件事。因此，我们保留原来的证据和答案，只改变显示出来的把握数字。')
p('这里把“有多少把握”称为 confidence，中文用“置信度分数”。它是模型收到的消息内容，不是我们已经验证过的真实可靠性。一个人写 90%，不代表他真的有 90% 的正确率。这个实验首先要测的是这串数字对接收者的影响，而不是评选谁最可靠。')
p('最终想回答的群体问题则多了一步：如果一个人的判断被改变，他接下来发给别人的消息也可能改变，其他人的判断又可能受影响。我们希望用第一步测出的反应规律，预测这种后续变化。但要先把第一步测清楚，不能从“某个回答变了”直接跳到“整个群体被带偏了”。')
sub('先用一个不涉及具体题目的例子说明研究目标')
example('说明性例子，不是已经观测到的实验结果','某题正确答案是 A。六个模型第一次回答中，四个选 A、两个选 B。接下来让它们看同伴的答案。我们想知道：如果把高分给正确的两个人，和把同样的高分给错误的两个人，讨论结果会不会不同？')
table(['成员','固定的第一次答案','情况一：正确者拿高分','情况二：错误者拿高分'],[
 ['1','A（对）','95%','55%'],['2','A（对）','95%','55%'],['3','A（对）','55%','55%'],['4','A（对）','55%','55%'],['5','B（错）','55%','95%'],['6','B（错）','55%','95%']])
p('两种情况都有四票 A、两票 B，也都有两个 95% 和四个 55%。人没有换，答案没有换，只有高分属于谁变了。这样，如果后续判断不同，我们才有条件研究“分数归属”这个因素。真实实验还要做多道题和重复调用，不能只比较一次。')
steps([('目标一：测下一次判断','固定题目和初始意见，只换分数，看看接收者下一次怎么答。这是一次回答更新的实验。'),('目标二：预测群体讨论','用前面测出的规律，事先预测新题中六个模型接下来几轮会怎么选，再与实际讨论结果比较。'),('目标三：检查影响能否继续传递','第一轮给出分数，之后去掉分数，检查先前的影响是否通过变化后的答案或理由继续传播。proposal 还计划比较不同交流结构。')])
conclusion('proposal 的最终目标不止是证明“数字会改变回答”，还要解释这种局部变化何时会影响整个群体，并提前预测这种影响。我们目前只完成了其中一部分。')

section('tasks','附录 A｜为什么最后选了需求预测题','这里回顾找题过程；正文直接介绍最终选定的任务，不需要先读这部分。')
table(['任务','模型需要做什么','答案或参考值从哪里来','为什么试这类题'],[
 ['逻辑判断','判断一组前提是否一定推出某个命题。','程序枚举所有可能的真假赋值，得到确定的正确答案。','先找能稳定核对对错、又不会几乎全对的题。'],
 ['供应商选择','比较 A、B 两个供应商的总净效益，选更高者。','把各条独立审计记录相加。','让不同成员先掌握不同资料，产生真实初始意见。'],
 ['市场需求预测','根据调查信号判断需求高或低，并报告“高需求”的概率。','程序先生成真实需求，再生成有噪声的调查；理论概率也可算出。','直接比较“能看原始证据”和“只能听别人建议”时的反应。']])
p('最开始还试过模运算状态追踪和贝叶斯计算题，主要是为挑选合适的难度。它们在小样本中大多太容易，因此后续先转向逻辑题。所有已完成的真实运行都使用同一个模型 ID：openai/gpt-5.6-luna；尚未做 GLM、Qwen 等模型的对照。')
sub('为什么中途换题型？')
p('逻辑题里，模型可以直接重新解题，不一定需要同伴；而且先前答案是人为设定的。供应商题解决了“初答是否真实产生”的问题，但所有资料公开后，模型几乎都能算对。于是我们又设计了需求预测题，把“是否能检查同伴的原始证据”作为明确的对照。')
conclusion('这三类题是在逐步改进实验，不是同一道题的三个版本。不同阶段改变了信息内容和测量指标，结果要分开解释。')

section('logic','附录 B｜前期探索一：逻辑题','保留难度筛选、新题复核、输出检查，以及逻辑题分数干预的过程和结果。')
sub('题目是什么：什么叫“逻辑蕴含”？')
example('最小例子','前提一：小王是学生。前提二：所有学生都有学生证。问题：这些前提是否一定说明小王有学生证？答案是“是”。如果只知道“有些学生有学生证”，就不能保证小王有。实际实验用布尔变量和“与、或、非”代替自然语言，方便程序精确核对。')
p('实际 L2 题有 7 个真假变量、28 条前提，问这些前提是否一定推出指定命题。例如，“是否一定推出 X1 为真？”程序检查全部 128 个赋值；只要发现一个同时满足前提、但 X1 为假的赋值，答案就是“不蕴含”。这些前提保证可以同时成立。')
detail('看一条实际题目的简短核验例子')
p('20 题扩样中的 v4 问“是否必然推出 X1”。有 6 个赋值满足全部 28 条前提；其中 (X1,…,X7)=(0,0,1,0,1,0,1) 就满足全部前提且 X1 为假，因此正确答案是不蕴含。六次真实回答为 A、A、A、B、A、A，只有第四次错；这次错误回答还报告了 99% 的把握。')
p('完整题面和六次理由保存在 runs/expansion-luna-logic-l2-20260920/DISAGREEMENT_ITEMS.md。这条案例说明实际题目怎样核验；后续没有只挑这类出现分歧的题来报告干预效果。')
enddetail()
sub('先校准难度：避免六个人一开始就全对')
p('最初两道小测题中，六个模型都答对，没有可比较的正确/错误意见分歧。接着我们分阶段扩大题库。所谓“难度校准”，在这里仅指寻找合适的答对率与分歧率，不是校准模型报告的概率。')
table(['做了什么','样本与设置','看到什么'],[
 ['三题型、四等级初筛','24 题，每题六次，共 144 次；无同伴信息。','逻辑 L1/L2 比其他层更常出错，成为候选。'],
 ['L1/L2 新题复核','各两题，每题六次。','L1 全对；L2 10/12 对，仍有一题出现分歧。'],
 ['L2 扩到 20 道新题','每题六次；全部题都保留。','114/120 对，只有三题出现分歧；“不蕴含”占了 17/20。'],
 ['改用 40 道平衡题','蕴含/不蕴含各 20，每类 A/B 正确选项各半。','186/230 有效回答正确（80.9%）；15 道题的完整六次回答有对有错。']])
p('这里平衡的是题目类别，不是强行让六个模型三对三错。筛题只用程序算出的正确答案，不用模型表现。原定候选标准是：有效答对率在 30%-85% 之间、无效率不超过 10%，且至少有一道完整题出现对错分歧。')
sub('再检查输出：不要把没输出完当作答错')
p('40 题校准中，有 8 次输出因 2048 token 预算耗尽而没有最终答案，另 2 次格式错误。我们对那 8 道曾失败的题重新做了 48 次测试，同时把上限提高到 8192、固定 medium 推理设置、要求严格 JSON。新测试 48 次全部有效。因为三项设置一起改了，不能认定单独提高上限就解释了改善。')
sub('正式对照怎么做：保持同伴答案不变，只交换分数')
example('说明性例子：题目正确答案为 B','接收者看到四份报告，依次是 A、B、B、A。第一种情况：两份 B 都标 95%，两份 A 都标 55%；第二种情况反过来。再加两种对照：大家都是 75%，以及完全不显示分数。接收者重新回答同一道题。')
p('这一步只有一个实际接收者在回答。四份同伴报告和接收者“上一轮的答案”均是程序预设的，不是六个模型刚刚讨论产生的。我们保留全部 40 道平衡题，每题四种情况各调用三次，共计划 480 次。题目、身份、答案顺序相同，改变的只有分数。')
p('计算时，先求同一道题“错误方高分时的错误率”减去“正确方高分时的错误率”，再对题平均。例如，前者 2/3 错、后者 1/3 错，差就是 +33.3 个百分点。正数才表示错误高分增加了错误。')
table(['检查','结果','如何理解'],[
 ['四条件比较','39 道完整题平均 -1.71 个百分点；95% 描述区间 [-8.55,+5.13]。','区间跨过零，不能清楚确定方向。'],
 ['旧题增加分差','用 .80/.70、.90/.60、.95/.55，各交换归属；加等分与隐藏，共八条件。每格三次，960 次请求。','分差增加 .10 时，错误率差平均下降 4.63 个百分点，方向与原预期相反。'],
 ['换 40 道新题复核分差','八条件、重复次数、提示和计算方法都不变。','同一趋势变为 -0.26 个百分点，区间 [-4.23,+3.57]，没有明确重复。']])
p('错误方高分的标签已对照真值逐条核对，没有写反。后来又检查了两批共 80 道题：题目类别和同题重复回答都会带来差异，但这些是看过结果后的分析，不能由此确定反向结果的原因。每种情况只有三次回答，也不足以精确估计单题效应。')
conclusion('逻辑题实验没有提供稳定的证据，证明“错误者拿高分就更容易把别人带错”。旧题中的反向趋势在新题上没有明确复现。它也暴露出一个设计限制：同伴意见是预设的，接收者可以自行重做整道题。')

section('supplier','附录 C｜前期探索二：供应商题','保留真实私人信息初答、局部更新与群体预测的探索。这些结果解释了后来为什么改用需求预测。')
sub('题目是什么：选择总净效益更高的供应商')
p('每道题有供应商 A 和 B，共七条审计记录：一条大家都能看到，六条分别由六名成员各掌握一条。记录上的数值可以直接相加。第一轮每个人只能看到公共记录和自己的私人记录；题面规定，没看到的记录中，A 与 B 的差值按期望零处理。')
