p('这一题六个模型真实初答是 B、A、B、B、B、A。全部信息公开以后，A 的总分比 B 高 3，所以最终应该选 A。最初选 B 的人，在只知道自己的资料时不一定推理错了；“初答错误”这里只表示与全信息答案不同。')
sub('实验怎么做')
steps([('准备训练题与新测试题','固定 8 道训练题和 8 道测试题。每题生成六个真实初答，另外做一次全信息单模型答题对照。'),('在训练题上测一次更新','公开全部资料。在一名初答正确者和一名错误者之间交换 95%/55%，另四人固定 75%；再加全体等分和隐藏分数。每人每种情况回答一次。'),('先作预测，再真正跑群体','只用训练题学习下一次选择规律。对新测试题预先保存六人两轮预测，然后才运行实际两轮更新。首轮显示分数，第二轮隐藏分数。'),('检查预测是否因分数而更准确','比较两个预测器：一个知道显示分数，另一个不知道。两者使用相同训练回答与其他输入。')])
p('严格的局部主比较只用未被交换分数的四名成员，因为他们都能同时看到两名交换对象，看到的分数集合完全相同。六人成员仍全部参加测试题的群体更新。')
sub('结果是什么')
table(['比较','实际结果'],[['训练题：正确者拿高分 vs 错误者拿高分','两种情况的主要比较接收者全部答对，错误率差为 0。'],['新测试题：第一轮','三种分数组合下，六人都全部答对。'],['新测试题：第二轮','正确者高分的分支错 0/48；错误者高分的分支错 2/48；隐藏分数分支错 1/48。'],['预测是否因为加入分数而改善','没有。两轮中，知道分数的预测器误差都略高于不知道分数的预测器。']])
p('第二轮表面上出现了差别，但核验发现：同一道题、同一成员在三个分支收到的请求内容完全相同。第一轮大家已经全对，第二轮又不显示分数、也不带入更早历史，所以早先分数不再通过输入传递。这几次错误差异只能说明相同输入也会产生不同响应，不能作为“置信度影响继续传播”的证据。')
conclusion('真实初答和群体预测的流程已经实现，但这类题在全部资料公开后太容易，几乎没有可测的分数影响。因此，proposal 中“用局部影响预测群体影响”的关键目标仍未得到验证。')

section('demand-task','最后选定的题：预测一种产品的市场需求','正文从这一题讲起。我们要比较：一个人能看到同伴的原始调查时，和只能看到同伴建议时，会怎样使用置信度分数。')
sub('模型收到的题目，通俗地说是什么')
example('题面内容的中文说明','一种新产品的实际市场需求可能高，也可能低，先验各占 50%。每位分析员有三份调查，每份调查判断正确的概率是 60%；给定真实需求后，各份调查独立。你要选择 A（低需求）或 B（高需求），并报告高需求的概率 P(B)。P(B)>50% 时选 B，否则选 A。')
sub('这是一道怎样的“经济学题”？')
p('它是程序生成的简化市场判断题，不是真实公司的销售数据，也没有测量真人的经济行为。选择市场需求这个背景，是为了让“每个人掌握部分资料、需要参考别人”这件事容易理解。目前结果适用于这套受控的信息规则，不能直接写成现实市场或人类社会中的规律。')
p('一道题对应同一个市场。六名分析员判断的是同一个市场的需求高低，但各自拿到三份不同调查。换一道新题时，程序重新生成市场状态和十八份调查。我们知道程序生成的真实状态，模型不知道；实验者知道答案，不意味着模型收到的题目包含答案。')
sub('先分清三种百分数，后面的表就容易读了')
table(['数字','它回答什么问题','本例的具体含义'],[
 ['调查准确率：60%','一份调查有多容易报对？','如果实际需求高，每份调查有 60% 概率报高；如果实际低，有 60% 概率报低。这是题目的固定规则。'],
 ['P(B)：例如 40%','这个接收者认为实际需求高的可能性多大？','B 始终代表高需求。P(B)=40% 意味着认为高需求有 40%、低需求有 60% 的可能。'],
 ['显示置信度：例如 A，60%','报告者声称自己选的那个答案有多可靠？','A，60% 表示对低需求有 60% 把握；B，60% 表示对高需求有 60% 把握。分数相同，支持的方向可以相反。']])
p('因此，“选 A，置信度 60%”与“高需求概率 40%”在未经干预时表达的是同一个判断。后面人为交换的是同伴报告上的置信度；我们记录的结果则是接收者重新给出的高需求概率 P(B)。输入的分数和输出的概率不是同一个变量。')
conclusion('这道题要求模型在有噪声的信息下作判断，不要求它凭空知道真实市场状态。后面的实验要看：在调查和初答已经固定时，只换别人报告上的数字，接收者会怎样重新判断。')
p('程序先生成市场实际需求，再生成调查结果。调查会出错，所以看到一份“高”并不意味着实际一定高。一个模型只看到自己的三份调查，其他五名成员也是如此，各自先真实作答。没有让模型凭空扮演“专家”或按照指定立场回答。')
sub('用最新复核中的第一道真实题来看')
table(['成员','自己的三份调查','真实第一次选择','报告高需求的概率'],[[f'成员 {j}','、'.join('高' if x=='high' else '低' for x in case['signals'][j]),'B：高需求' if root['initial'][j]['answer']=='B' else 'A：低需求',f"{100*root['initial'][j]['p_B']:.2f}%"] for j in range(6)])
p('这题实际需求是低，六人中五人选 A、一人选 B。实际需求只用于记录和评价，没有告诉模型。总共十八份调查里有六份“高”、十二份“低”。下文专门看成员 3：他自己看到“低、高、低”，第一次报告高需求概率为 40%。')
example('把自己放在成员 3 的位置','你手里只有三份调查：低、高、低。你知道每份调查只有 60% 的准确率，因此不能断言需求一定低。现在别人发来“我认为需求低，77.14% 把握”和“我认为需求高，60% 把握”。你会怎样调整判断？如果只把这两个把握数字对调，你会不会给出不同概率？这就是后面实际比较的内容。')
p('成员 3 的 40% 也能直接算清楚：如果真实需求高，出现“低、高、低”的概率是 .4×.6×.4=.096；如果真实需求低，这组调查出现的概率是 .6×.4×.6=.144。高低需求原先各半，因此看到这组调查后，高需求概率为 .096/(.096+.144)=.4。这个计算说明他在收到同伴建议前的起点。')
p('不用公式也可以理解：假想一开始有同样多的高需求和低需求市场。低、高、低这组调查，在低需求市场里更容易出现，所以看完后应该更偏向低需求；但调查有噪声，不能把高需求的可能性降到零。40% 就是按照题目规则计算的高需求概率。上面的乘法成立，是因为题目规定：在实际需求给定后，各调查独立。')
sub('为什么两个高低分设为 60% 和约 77.14%？')
p('它们来自题目自己的概率规则。三份调查中两份高、一份低时，高需求概率是 60%；三份都高时，高需求概率约为 77.14%。反过来，三份都低时，对低需求的把握也是约 77.14%。因此，这两种分数在当前任务中有容易理解的来源。')
p('但实验里显示的分数会被我们替换，不能再认为它一定忠实反映那个人的调查。模型看到的是“报告者认为自己所选答案正确的概率”，不会被告知我们正在交换分数。程序也不要求模型相信高分，更不按分数强行选最终答案。')
conclusion('这类题同时有真实初始分歧、明确的信息来源和可计算的概率。它让我们有条件区分：模型拿得到原始证据时会怎样，拿不到时又会怎样。')

section('demand-design','同一道题，我们具体改变了哪两件事？','先固定六人的真实初答，再建立对照。这里的关键是：每次比较只改变事先规定的内容。')
sub('第一件事：是否显示同伴的原始调查')
table(['接收者看到什么','完整证据','只看建议'],[['自己的资料','自己的三份调查、自己的真实前答和概率。','完全相同。'],['其他五人的意见','各自的真实 A/B 答案和显示分数。','完全相同。'],['其他五人的原始调查','显示各人的三份调查。','不显示。'],['其他人的长理由或原始概率','不额外提供。','不额外提供。']])
p('所以“只看建议”不等于什么证据都没有：他仍知道自己的三份调查，只是不知道同伴为什么得出那些建议。两种信息条件下，成员身份、报告顺序和初始意见都不变。')
sub('第二件事：把同一对高低分分给谁')
p('在这道真实题中，选中成员 4（建议 A）和成员 1（建议 B）交换分数。接收者成员 3 能同时看到他们两人的报告。')
table(['固定的建议者','固定的建议','情况一：A 方拿高分','情况二：B 方拿高分'],[['成员 4','A：低需求','77.1429%','60%'],['成员 1','B：高需求','60%','77.1429%'],['其余成员','保持原始建议','各自分数不变','各自分数不变']])
p('例如，成员 4 一直建议 A，他的报告内容不会被改成 B。我们只把成员 4 和成员 1 身旁的两个数字交换。这样，两次输入里的票数相同、数值集合相同，仅数字对应的立场变了。')
sub('一次完整实验按什么顺序执行')
steps([('先取得真实初答','每题六人分别看自己的调查，各回答一次。若全体初答一致，就不进入分数交换，不重新抽题来凑分歧。'),('选交换对象和接收者','从 A/B 两方各选一人交换分数，再从其余四人中选两位接收者。接收者都能看到两份被交换的报告。'),('建立全部对照输入','每位接收者同时测试完整证据和只看建议；每种信息条件再测 A 高分、B 高分、交换两人等分、全体隐藏分数。'),('重复并比较','每种输入调用两次，保存原始回答。同一题的两名接收者与两次重复先平均，再对不同题平均。')])
p('“等分”只把那两名交换对象改为 68.5714%，其他成员保持自己的固定分数；“隐藏”则不显示任何人的分数。主要结论来自 A 高分与 B 高分的比较，其余两种用于辅助观察。')
p('每个合格题的更新调用数为：2 名接收者 × 2 种信息条件 × 4 种分数组合 × 2 次重复 = 32 次。初始六人还各有一次回答。这些更新各自从同一组初答出发，不把某次更新继续传给下一人。')
conclusion('这一轮严格测的是“一次判断会不会改变”。它有六人的真实初答，但只观察两个接收者的单步更新，尚未跑六人完整的多轮讨论。')

section('demand-case','先看一个人的真实结果，再看整批平均','回到成员 3。他自己的三份调查和第一次答案始终相同，只改变同伴分数的归属。')
sub('先把他第二次收到的内容完整摆出来')
p('以下用中文重述实际输入中的任务信息，便于阅读；不是逐字复制英文提示。表格按成员编号排列，实际请求中的同伴顺序在配对比较中保持不变。接收者是成员 3，所以同伴表里有其余五人，不包括他自己。')
example('两种输入共同保留的开头','你正在判断同一个市场的需求。A 表示低需求，B 表示高需求。高低需求原先各占一半，每份调查准确率为 60%，给定真实状态后各调查独立。你自己的调查是：低、高、低。你先前选择 A，报告的高需求概率为 40%。现在参考其他五位分析员的报告，重新给出 A/B 选择、高需求概率和简短理由。')
p('实际提示还明确要求：不要假定知道没有显示的调查；每份调查只能计算一次，不能因为别人提到它就重复计数；显示置信度只是报告者声称的把握，不是保证。模型也被告知，预测将按它报告的概率与实际状态之间的平方误差评价。各分支都使用这些相同要求。')
table(['同伴','初答：两边完全相同','输入一：A 方拿高分','输入二：B 方拿高分'],[
 ['成员 0','A：低需求','60%','60%'],['成员 1','B：高需求','60%','77.1429%'],['成员 2','A：低需求','60%','60%'],['成员 4','A：低需求','77.1429%','60%'],['成员 5','A：低需求','约 77.1429%','约 77.1429%']])
p('请只看成员 1 和成员 4 两行：他们的 A/B 答案没有换位置，也没有改口；变化的是旁边的两个数字。成员 5 原来就有较高的分数，两边都保留。这里的“A 方拿高分”不是说所有选 A 的人都拿高分，而是说被选中的 A 方成员 4 拿到两枚交换分数中较高的那一枚。')
p('这样，两边都是四名同伴选 A、一名选 B；两边也都是三个约 60%、两个约 77.14%。如果把所有分数取平均，平均数没有改变。改变的只是高分支持谁，因而我们不会把“高分更多了”或“多数意见变了”误当成分数归属的影响。')
sub('“完整证据”具体多给了什么？')
table(['同伴','完整证据时额外显示的调查','只看建议时'],[[f'成员 {j}','、'.join('高' if x=='high' else '低' for x in case['signals'][j]),'这一栏不提供'] for j in [0,1,2,4,5]])
p('完整证据时，成员 3 可以把表里的十五份调查与自己的三份合并，共十八份。只看建议时，他仍知道别人各有三份调查，却看不到这十五份调查的具体高低。两种信息条件都保留上面的同伴选择和分数。')
table(['分支','能看同伴调查吗？','交换的两个分数给谁？','模型要输出什么？'],[
 ['完整证据，A 方高分','能','成员 4：77.1429%；成员 1：60%','重新选择 A/B，并报告 P(B)'],
 ['完整证据，B 方高分','能','成员 4：60%；成员 1：77.1429%','同上'],
 ['只看建议，A 方高分','不能','成员 4：77.1429%；成员 1：60%','同上'],
 ['只看建议，B 方高分','不能','成员 4：60%；成员 1：77.1429%','同上']])
p('这四个分支分别从同一个初始状态开始。不是先让他看 A 方高分、再告诉他“现在改成 B 方高分”；每次请求都重新提供原来的初答和相应同伴消息，不提供其他分支的回答。因此，比较的是不同输入下的一次更新，而不是一个人连续改主意的过程。等分与隐藏分数两个辅助条件也同样独立进行。')
conclusion('现在可以明确说出实验操纵：同一题、同一位接收者、同一套初答，分别测试“能不能看到同伴调查”和“交换的高分给 A 还是 B”。两件事交叉比较，才能看出缺少原始证据时是否更依赖分数。')
sub('实际输出：每种输入调用两次，而不是只留一次好看的回答')
rawrows=[]
for v,label in [('full','完整证据'),('advice','只看建议')]:
    for a,alabel in [('A_high','A 方高分'),('B_high','B 方高分')]:
        rr=[r['parsed'] for r in updates if r['item_id']=='demand-00' and r['member']==3 and r['visibility']==v and r['arm']==a]
        assert len(rr)==2
        rawrows.append([label,alabel,f"{100*rr[0]['p_B']:.8f}%",f"{100*rr[1]['p_B']:.8f}%",'、'.join(r['answer'] for r in rr)])
table(['信息条件','高分归属','第一次输出 P(B)','第二次输出 P(B)','两次所选答案'],rawrows)
p('表里的概率来自模型实际输出。程序计算的理论概率只用于核对，没有替模型填入答案。重复调用是因为相同输入也可能得到不同响应；我们保留两次，再取平均。这些重复不是新的市场题，也不是第二轮讨论。')
rows=[]
for v,label in [('full','完整证据'),('advice','只看建议')]:
    a,b=casep(v,'A_high'),casep(v,'B_high')
    rows.append([label,f'{100*a:.4f}%',f'{100*b:.4f}%',f'{100*(b-a):+.4f} 个百分点','两种情况均选 A'])
table(['成员 3 的信息条件','A 方高分时的 P(B)','B 方高分时的 P(B)','概率变化','最终选择'],rows)
p('完整证据时，他能自己数清十八份调查，两个条件下都给出约 8.07% 的高需求概率。只看建议时，他不知道同伴的调查，只能看到他们的答案和分数；高分从 A 方移给 B 方后，高需求概率从约 3.76% 上升到 16.49%。')
example('怎样理解“增加 12.74 个百分点”？','16.49%-3.76%≈12.74 个百分点。这不是说答对率提高了 12.74%，也不是说他改变了选项。他两次仍选 A，只是对高需求的概率判断明显不同了。')
steps([('先算 A 方高分时的平均','只看建议时，两次都是 3.75532000%，所以平均仍是 3.75532000%。'),('再算 B 方高分时的平均','两次都是 16.49484536%，所以平均仍是 16.49484536%。'),('两种平均相减','16.49484536% − 3.75532000% = 12.73952536 个百分点。正数表示把高分给 B 方后，接收者更倾向高需求。'),('最后检查选项是否改变','这两个概率都低于 50%，按题目的选择规则都应该选 A。所以这个人有概率变化，却没有 A/B 翻转。')])
p('也不要用“第一次的 40% 减去第二次的 3.76%”作为分数影响。这期间不仅出现了分数，还新增了五个人的建议。我们真正要比较的是已经收到同样五份建议的两种情况：A 方拿高分与 B 方拿高分。这样才是在隔开其他变化后，测分数归属的作用。')
sub('为什么看到全部调查后，结果约为 8.07%？')
p('十八份调查中有六份高、十二份低。如果实际需求高，出现这组调查的概率是 0.6 的六次方乘 0.4 的十二次方；如果实际需求低，则是 0.4 的六次方乘 0.6 的十二次方。前者除以后者等于 (2/3) 的六次方，即 64/729。这表示这组调查更支持低需求。')
p('高低需求最初各半，因此把上面的相对可能性换成高需求概率，就是 64/(64+729)=64/793≈8.070618%。完整证据下，交换分数并没有改变任何调查，所以按这些调查计算的参考概率也不会改变。模型两种回答都接近这个值。这个参考概率不等于实际状态：实际需求是低，但有噪声的调查仍然给高需求留下约 8.07% 的可能。')
sub('图 1：同一接收者，在四种输入下报告了什么')
vals=[100*casep(v,a) for v in ('full','advice') for a in ('A_high','B_high')]
labels=['完整证据 / A 高分','完整证据 / B 高分','只看建议 / A 高分','只看建议 / B 高分']
g=['<svg viewBox="0 0 760 300" role="img" aria-label="真实案例成员3报告的高需求概率">']
for t in [0,5,10,15,20]:
    y=240-t/20*190;g.append(f'<line x1="60" x2="740" y1="{y}" y2="{y}" stroke="#dce4e9"/><text x="47" y="{y+4}" text-anchor="end">{t}</text>')
g.append('<text x="60" y="23">报告的高需求概率（%）</text>')
for i,(val,lab) in enumerate(zip(vals,labels)):
    x=92+i*168;hh=val/20*190;color='#2b718d' if i%2==0 else '#b45e3d'
    g.append(f'<rect x="{x}" y="{240-hh}" width="72" height="{hh}" fill="{color}" rx="3"/><text x="{x+36}" y="{232-hh}" text-anchor="middle">{val:.2f}</text><text x="{x+36}" y="270" text-anchor="middle" font-size="12">{lab}</text>')
g.append('</svg>')
parts.append('<figure>'+''.join(g)+'<figcaption>图 1。横轴是信息条件与高分归属，纵轴是成员 3 报告的高需求概率。蓝色为 A 方高分，橙色为 B 方高分。每根柱为相同输入两次回答的平均，没有误差线。此图只解释一个真实案例，整批结论见下一节。</figcaption></figure>')
p('这是按题号选出的第一道合格题、按记录顺序选出的第一位接收者，并没有挑概率变化最大的例子。来源是最新复核批次的 demand-00；另一名接收者的结果也包含在整批统计中。')
conclusion('这个例子说明，分数可以改变模型报告的概率，而不改变最后的 A/B 选择。如果只统计有没有改答案，就会漏掉这样的影响。')

section('demand-results','整批实验得到什么结果？新实例是否重复出现？','一个例子只能帮助理解。要判断有没有较一致的现象，必须把预先规定的题全部纳入，并单独做新实例复核。')
sub('两批数据分别怎样取得')
p('第一批生成 16 个市场，实际高、低需求各 8 个；16 题初答都有分歧，全部进入更新。共 96 次初答和 512 次更新，608 次全部有效。')
p('复核批次先固定原协议，只换任务生成种子，再生成 16 个市场、重新取得初答。15 题有分歧，1 题全体一致，按原规则排除且不补题。共 96 次初答和 480 次更新，576 次全部有效。模型、提示、分数、重复次数和计算方法保持不变。')
sub('我们计算的“影响”具体是什么')
p('对同一道题，计算“B 方拿高分时报告的高需求概率”，减去“A 方拿高分时的概率”。先把两位接收者、两次重复的四个差值平均，再对题平均。正数表示：仅仅把高分移向 B，模型就把概率往 B 方向调整。')
sub('从刚才那个人，到一整道题，再到十五道题')
p('同一道题还测试了成员 2。之所以再选一个接收者，是为了不把某一名接收者的反应当成整道题的结果。两位接收者都不参与分数交换，因此都能同时看到两份被交换的同伴报告。这里有六个真实初答，但只有两个人接受后续更新测试。')
ag=[]
for member in [3,2]:
    means=[]
    for arm in ['A_high','B_high']:
        rr=[r['parsed']['p_B'] for r in updates if r['item_id']=='demand-00' and r['member']==member and r['visibility']=='advice' and r['arm']==arm]
        means.append(mean(rr))
    ag.append([f'成员 {member}',f'{means[0]*100:.8f}%',f'{means[1]*100:.8f}%',f'{(means[1]-means[0])*100:.8f} 个百分点'])
table(['只看建议','A 方高分：两次平均','B 方高分：两次平均','该接收者的差值'],ag)
p('成员 2 在 A 方高分条件下，两次分别报 3.7553% 和 1.7037%，平均是 2.7295%；B 方高分时平均是 16.49484536%。所以他的差值是 13.76534536 个百分点。这也展示了为什么不能只用一次输出：相同输入本身会有波动。')
example('这道题的计算结果','先合并两位接收者：(12.73952536 + 13.76534536) ÷ 2 = 13.25243536 个百分点。这才是 demand-00 这道题在“只看建议”条件下的效应。')
p('复核批次的另外十四道合格题也各自这样计算。最后把十五道题的效应相加，再除以十五，得到约 22.48 个百分点。每道题权重相同。因此，单个例子的 12.74、这道题的 13.25、整批的 22.48 并不矛盾：它们分别在回答“这个人变化多少”“这道题平均变化多少”“这批题平均变化多少”。')
p('22.48 也不是模型最终报告的高需求概率，更不是正确率。它是两种分数安排之间的平均概率差。例如，从 20% 变到 42.48% 也是增加 22.48 个百分点，从 60% 变到 82.48% 也是增加同样多；这些例子只解释单位，不是新增实验结果。')
conclusion('几百次请求不等于几百道独立题。我们先把同一题内部的重复与接收者合并，最终比较的是第一批十六道题、新批十五道题的平均效应。')
