toc=[(sid,titles[sid]) for sid in order]

css='''
:root{--ink:#243441;--muted:#65737d;--blue:#286b82;--line:#dce5e9;--bg:#f3f5f5}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:26px}body{margin:0;color:var(--ink);background:var(--bg);font:17px/1.95 "Microsoft YaHei",system-ui,sans-serif}a{color:var(--blue)}aside{position:fixed;inset:0 auto 0 0;width:240px;padding:32px 20px;background:#fafcfc;border-right:1px solid var(--line);overflow:auto}aside .brand{font-size:11px;letter-spacing:1.4px;color:var(--blue);font-weight:700}aside h2{font-size:18px;margin:5px 0 22px}nav a{display:block;padding:9px 8px;margin:4px 0;font-size:13px;line-height:1.7;text-decoration:none;color:var(--muted);border-left:2px solid transparent}nav a:hover{background:#eaf1f4;color:var(--blue);border-color:var(--blue)}main{margin-left:240px;padding:36px 5vw 70px}header,section{max-width:900px;margin:0 auto 28px;background:white;border:1px solid var(--line);border-radius:6px;padding:38px 43px}header{border-top:4px solid var(--blue)}.eyebrow,.num{font-size:12px;color:var(--blue);font-weight:750;letter-spacing:1px}h1{font-size:34px;line-height:1.5;letter-spacing:-.7px;margin:13px 0 20px}h2{font-size:27px;line-height:1.55;margin:5px 0 16px}h3{font-size:19px;color:var(--blue);margin:29px 0 12px}.lead{font-size:18px;color:var(--muted);line-height:1.9}p{margin:15px 0 19px}.conclusion{background:#eef5f5;border-left:3px solid #6797a1;padding:16px 20px;margin-top:26px}.conclusion strong{font-size:13px;color:var(--blue)}.conclusion p{margin:6px 0 0}.example{background:#fbf7ee;border-left:3px solid #bb9452;padding:17px 20px;margin:22px 0}.example strong{font-size:13px;color:#856628}.example p{margin:7px 0 0}.steps{padding-left:27px}.steps li{padding-left:8px;margin:20px 0}.steps strong{font-size:17px}.steps p{margin:4px 0;color:#475966}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:4px;margin:24px 0}table{border-collapse:collapse;width:100%;min-width:590px;font-size:13.5px;line-height:1.85}th,td{padding:12px 14px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}th{background:#eef3f5;font-weight:650}tr:last-child td{border-bottom:0}td:first-child{min-width:110px}details{margin:22px 0;border:1px solid var(--line);border-radius:4px;padding:0 19px;font-size:15px}summary{cursor:pointer;padding:14px 0;font-size:14px;color:var(--blue);font-weight:650}details[open] summary{border-bottom:1px solid var(--line);margin-bottom:17px}details p{overflow-wrap:anywhere}figure{margin:24px 0;border:1px solid var(--line);padding:14px 12px 0;border-radius:4px;overflow-x:auto}svg{display:block;width:100%;min-width:600px;height:auto;font-family:"Microsoft YaHei",sans-serif;font-size:13px;fill:var(--ink)}figcaption{font-size:12px;line-height:1.85;color:var(--muted);padding:15px 7px;border-top:1px solid var(--line);margin-top:8px}.route{font-size:14px;padding:17px 20px;background:#f3f6f7;border-radius:4px}.note{font-size:12px;color:var(--muted)}.footer{max-width:900px;margin:30px auto;font-size:12px;color:var(--muted)}button{font:inherit;font-size:12px;padding:6px 11px;border:1px solid var(--line);color:var(--blue);background:white;border-radius:4px;cursor:pointer;margin-right:5px}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #85aabc;outline-offset:3px}.tools{margin-top:18px}
@media(max-width:1100px){aside{width:205px;padding:23px 13px}main{margin-left:205px;padding:25px 22px}header,section{padding:29px 27px}h1{font-size:29px}h2{font-size:24px}}
@media(max-width:760px){body{font-size:16px}aside{position:relative;width:100%;padding:18px 20px;border-right:0;border-bottom:1px solid var(--line)}aside h2{margin:0 0 10px}nav{display:flex;overflow:auto;gap:7px}nav a{flex:0 0 170px;background:#eef3f5;padding:8px;font-size:12px;margin:0}main{margin:0;padding:14px 10px 40px}header,section{padding:25px 19px}h1{font-size:27px}h2{font-size:23px}.lead{font-size:17px}.table-wrap{margin-left:-4px;margin-right:-4px}table{font-size:12.5px}figure{padding:7px 0 0}.conclusion,.example{padding:14px 16px}details{padding:0 12px}}
@media print{aside,.tools{display:none}body{background:white;font-size:11pt}main{margin:0;padding:0}header,section{max-width:none;border:0;padding:8px 0;border-radius:0}section{break-before:page}h2,h3{break-after:avoid}.conclusion,.example,figure,table{break-inside:avoid}.table-wrap,figure{overflow:visible}table,svg{min-width:0}details{border:0;padding:0}summary{display:none}figcaption{font-size:9pt}}
'''
intro='''<header id="start"><div class="eyebrow">CONFIDENCE AGENTS / 从研究问题讲起</div><h1>我们想研究什么，<br>做了什么实验，得到了什么？</h1><p class="lead">这份报告先解释 proposal 的目标和题目本身，再一步步说明实验怎样设计。先不要求读者记住实验编号、公式或统计术语。</p><div class="route"><strong>阅读顺序</strong><br>为什么交换置信度分数 → 给模型什么题 → 逻辑题与供应商题教会了我们什么 → 市场需求实验如何做 → 真实例子与整批结果 → 距离 proposal 目标还差什么。</div><p>请始终区分两个问题：<strong>一个模型的下一次判断是否改变</strong>，以及<strong>这种改变是否会让整个群体走向不同结果</strong>。目前证据较充分的是前一个问题，后一个还没有验证完成。</p><div class="tools"><button id="expand" type="button">展开补充细节</button><button id="collapse" type="button">收起补充细节</button><button id="print" type="button">打印</button></div><p class="note">基于已保存的实验记录整理。示意例子与真实案例分开标注；本报告没有新增模型调用。</p></header>'''
intro=intro.replace('为什么交换置信度分数 → 给模型什么题 → 逻辑题与供应商题教会了我们什么 → 市场需求实验如何做 → 真实例子与整批结果 → 距离 proposal 目标还差什么。','proposal 的研究目标 → 最后选定的市场需求题 → 用一道真实题讲清输入与对照 → 单题结果 → 两批整体结果 → 目前结论。逻辑题和供应商题的前期探索放在附录。')
nav='<a href="#start">阅读说明</a>'+''.join(f'<a href="#{sid}">'+(f'{i+1:02d} · ' if i<7 else '')+H(title)+'</a>' for i,(sid,title) in enumerate(toc))
js='''document.getElementById('expand').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=true);document.getElementById('collapse').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);let state;window.addEventListener('beforeprint',()=>{state=[...document.querySelectorAll('details')].map(d=>[d,d.open]);state.forEach(([d])=>d.open=true)});window.addEventListener('afterprint',()=>{if(state)state.forEach(([d,o])=>d.open=o)});document.getElementById('print').onclick=()=>window.print();'''
doc='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>从 proposal 到实验结果 · Confidence Agents</title><style>'+css+'</style></head><body><aside><div class="brand">CONFIDENCE AGENTS</div><h2>从研究问题讲起</h2><nav aria-label="阅读目录">'+nav+'</nav></aside><main>'+intro+''.join(parts)+'<footer class="footer">数据来源：Proposal/main.pdf、各运行目录的实验清单、原始请求、结果和核验记录。<br>本文件包含完整正文与矢量图，可以离线阅读。</footer></main><script>'+js+'</script></body></html>'
assert 'sk-or-' not in doc
OUT.mkdir(parents=True,exist_ok=True)
target=OUT/'confidence_agents_experiment_report_zh.html'
target.write_text(doc,encoding='utf-8')
print(json.dumps({'html':str(target),'sections':len(toc),'figures':2,'experiments':len(ledger),'bytes':target.stat().st_size},ensure_ascii=True))
